negativeExample:
import org.eclipse.jface.action.IAction;

public class MyClass {
    @Override
    public final void run(IAction action) { // Already correct order
        System.out.println("Running action: " + action);
    }

    protected final String anotherMethod() { // Different modifiers
        return "test";
    }

    public static final String staticHelper() { // Public static final, not final public
        return "static";
    }

    final protected void protectedFinalMethod() { // Different modifiers
        System.out.println("Protected final");
    }
}
